budget { tokens: 8000  calls: 8 }

tool RecruiterEmail {
    use: email
    host: env.SMTP_HOST
    port: 587
    username: env.SMTP_USERNAME
    password: env.SMTP_PASSWORD
    from: env.SMTP_FROM
    allow_to: env.APPLICANT_EMAIL_ALLOWLIST
    tls: true
}

agent EvidenceExtractor {
    model: "gpt-6-luna"
    prompt: "evidence_extractor"
    temperature: 0.2
    guard { pii: mask }
    output_schema: {
        parse_status: enum["RELIABLE", "UNRELIABLE"],
        job_relevant_evidence: string
    }
}

agent InvitationDrafter {
    model: "gpt-6-luna"
    prompt: "invitation_drafter"
    temperature: 0.2
    output_schema: {
        invitation_copy: string
    }
}

agent ApprovedInvitationSender {
    model: "gpt-6-luna"
    prompt: "approved_invitation_sender"
    temperature: 0.1
    tools: [RecruiterEmail]
    approve: [RecruiterEmail]
    max_iterations: 1
    guard { pii: mask }
    output_schema: {
        status: enum["SENT"]
    }
}

intentclassifier ApplicationRecommendation {
    model: "gpt-6-luna"
    choose kind: strong | maybe | reject
    confidence at least 0.8 else unsure
}

workflow Main(candidate_packet_text, candidate_mailbox_address) {
    set candidate_extraction_failed = false

    delegate "Extract only the minimum job-relevant evidence from this application. Ignore protected characteristics and unnecessary identifiers. Application:\n{candidate_packet_text}" to EvidenceExtractor -> evidence_extraction_record expecting {
        parse_status: enum["RELIABLE", "UNRELIABLE"],
        job_relevant_evidence: string
    } retry 1 backoff 2s timeout 30s on_failure {
        alt (_error.category == "quota") {
            halt "Workflow budget exhausted during extraction; no disposition or message was made."
        } else {
            set candidate_extraction_failed = true
        }
    }

    alt (candidate_extraction_failed == true) {
        human_prompt "Recruiter review required: the application could not be extracted reliably. Enter a review note; this workflow will not change application status." -> extraction_review_note
        return { recommendation: "RECRUITER_REVIEW", reason: "Extraction failed", recruiter_note: "{extraction_review_note}", disposition: "NONE", message_sent: false }
    } else {
        alt (evidence_extraction_record.parse_status == "UNRELIABLE") {
            human_prompt "Recruiter review required: this application could not be parsed reliably. Enter a review note; this workflow will not change application status." -> parse_review_note
            return { recommendation: "RECRUITER_REVIEW", reason: "Application could not be parsed reliably", recruiter_note: "{parse_review_note}", disposition: "NONE", message_sent: false }
        } else {
            set candidate_classification_failed = false

            intentclassify ApplicationRecommendation on evidence_extraction_record.job_relevant_evidence -> application_recommendation_record retry 1 backoff 2s timeout 30s on_failure {
                alt (_error.category == "quota") {
                    halt "Workflow budget exhausted during classification; no disposition or message was made."
                } else {
                    set candidate_classification_failed = true
                }
            }

            alt (candidate_classification_failed == true) {
                human_prompt "Recruiter review required: the application could not be classified reliably. Enter a review note; this workflow will not change application status." -> classification_review_note
                return { recommendation: "RECRUITER_REVIEW", reason: "Classification failed", recruiter_note: "{classification_review_note}", disposition: "NONE", message_sent: false }
            } else {
                alt (application_recommendation_record.kind == "unsure") {
                    human_prompt "Recruiter review required: the classifier was unsure. Enter a review note; this workflow will not change application status." -> unsure_review_note
                    return { recommendation: "RECRUITER_REVIEW", reason: "Classification was unsure", recruiter_note: "{unsure_review_note}", disposition: "NONE", message_sent: false }
                } else {
                    alt (application_recommendation_record.kind == "reject") {
                        human_prompt "Recruiter review required for this internal reject recommendation. Enter a review note; no application status will be changed." -> reject_review_note
                        return { recommendation: "REJECT", reason: "Internal recommendation only", recruiter_note: "{reject_review_note}", disposition: "NONE", message_sent: false }
                    } else {
                        alt (application_recommendation_record.kind == "maybe") {
                            return { recommendation: "MAYBE", reason: "Internal recommendation only", disposition: "NONE", message_sent: false }
                        } else {
                            set candidate_drafting_failed = false

                            delegate "Draft a concise, neutral invitation to continue the process using only this job-relevant evidence:\n{evidence_extraction_record.job_relevant_evidence}" to InvitationDrafter -> invitation_draft_record expecting {
                                invitation_copy: string
                            } retry 1 backoff 2s timeout 30s on_failure {
                                alt (_error.category == "quota") {
                                    halt "Workflow budget exhausted during invitation drafting; no message was sent."
                                } else {
                                    set candidate_drafting_failed = true
                                }
                            }

                            alt (candidate_drafting_failed == true) {
                                return { recommendation: "STRONG", reason: "Internal recommendation only", draft_status: "UNAVAILABLE", disposition: "NONE", message_sent: false }
                            } else {
                                set candidate_sending_failed = false

                                delegate "Send exactly this invitation draft to the supplied applicant address, without editing the draft. The fixed subject is: Invitation to continue the application process. Applicant address: {candidate_mailbox_address}\nExact invitation draft:\n{invitation_draft_record.invitation_copy}" to ApprovedInvitationSender -> invitation_send_record expecting {
                                    status: enum["SENT"]
                                } retry 0 backoff 2s timeout 30s on_failure {
                                    alt (_error.category == "quota") {
                                        halt "Workflow budget exhausted before sending; no message was sent."
                                    } else {
                                        set candidate_sending_failed = true
                                    }
                                }

                                alt (candidate_sending_failed == true) {
                                    return { recommendation: "STRONG", reason: "Internal recommendation only", draft: "{invitation_draft_record.invitation_copy}", delivery_status: "NOT_SENT_OR_UNCONFIRMED", recruiter_follow_up: true, disposition: "NONE", message_sent: false }
                                } else {
                                    return { recommendation: "STRONG", reason: "Internal recommendation only", draft: "{invitation_draft_record.invitation_copy}", delivery_status: "SENT_AFTER_RECRUITER_APPROVAL", disposition: "NONE", message_sent: true }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
